create table if not exists public.stripe_webhook_receipts(id uuid primary key default gen_random_uuid(),provider_event_id text not null unique,event_type text not null,payload_sha256 text not null,status text not null check(status in('processing','processed','failed')),error_message text,processed_at timestamptz,created_at timestamptz not null default now());
alter table public.stripe_webhook_receipts enable row level security;revoke all on public.stripe_webhook_receipts from anon,authenticated;grant all on public.stripe_webhook_receipts to service_role;
create unique index if not exists subscriptions_stripe_customer_unique on public.subscriptions(stripe_customer_id) where stripe_customer_id is not null;
create unique index if not exists subscriptions_stripe_subscription_unique on public.subscriptions(stripe_subscription_id) where stripe_subscription_id is not null;
create table if not exists public.referral_codes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,code text not null unique check(code ~ '^[A-Z0-9]{6,12}$'),created_at timestamptz not null default now());
alter table public.referral_codes enable row level security;grant select,insert on public.referral_codes to authenticated;create policy "owners manage referral codes" on public.referral_codes for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
